export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

edits.newText:
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where we started so brick collision can sweep the whole path
  // (used by bounceBricks to avoid tunnelling, see #1).
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

