    if (brick.alive) {
      brick.alive = false;
      broken.push(brick);
    }

    if (axis === 'x' || axis === 'both') {
      if (!flippedX) {
        flippedX = true;
        ball.vx = -ball.vx;
      }
      // Push the ball out along x, away from the shallower side.
      const penL = x + ball.r - brick.x;
      const penR = brick.x + brick.w - (x - ball.r);
      x = penL < penR ? brick.x - ball.r : brick.x + brick.w + ball.r;
