// --- Brick bounce: issue #1 -------------------------------------------------

// A ball falling onto a brick from above must lose its downward speed and come
// to rest just above the brick's top face (per-face vy flip + push-out).

test('bounceBricks: ball bounced off the TOP face of a brick', () => {
  const brickObj = brick(200, 100);
  const ball = { x: 236, y: 140, r: 7, vx: 0, vy: 300 }; // center just over the brick
  const prevX = ball.x, prevY = ball.y - 40; // coming straight down
  bounceBricks(ball, [brickObj], prevX, prevY);
  assert.ok(ball.vy < 0, 'vertical velocity should flip up');
  assert.equal(ball.vx, 0, 'horizontal component must survive untouched');
  assert.ok(ball.y + ball.r <= brickObj.y, 'ball should be pushed above the brick');
  assert.equal(brickObj.alive, false, 'brick should be broken');
});

test('bounceBricks: ball bounced off the BOTTOM face of a brick', () => {
  const brickObj = brick(200, 100);
  const ball = { x: 236, y: 60, r: 7, vx: 0, vy: -300 }; // below the brick, going up
  const prevX = ball.x, prevY = ball.y + 40;
  bounceBricks(ball, [brickObj], prevX, prevY);
  assert.ok(ball.vy > 0, 'vertical velocity should flip down');
  assert.equal(ball.vx, 0);
  assert.ok(ball.y - ball.r >= brickObj.y + brickObj.h, 'ball should be pushed below the brick');
  assert.equal(brickObj.alive, false);
});

test('bounceBricks: ball bounced off the LEFT face of a brick', () => {
  const brickObj = brick(200, 100);
  const ball = { x: 258, y: 110, r: 7, vx: 300, vy: 0 }; // right of brick, moving left
  const prevX = ball.x + 40, prevY = ball.y;
  bounceBricks(ball, [brickObj], prevX, prevY);
  assert.ok(ball.vx > 0, 'horizontal velocity should flip right');
  assert.equal(ball.vy, 0, 'vertical component must survive untouched');
  assert.ok(ball.x - ball.r >= brickObj.x + brickObj.w, 'ball should be pushed right of the brick');
  assert.equal(brickObj.alive, false);
});

test('bounceBricks: ball bounced off the RIGHT face of a brick', () => {
  const brickObj = brick(200, 100);
  const ball = { x: 178, y: 110, r: 7, vx: -300, vy: 0 }; // left of brick, moving right
  const prevX = ball.x - 40, prevY = ball.y;
  bounceBricks(ball, [brickObj], prevX, prevY);
  assert.ok(ball.vx < 0, 'horizontal velocity should flip left');
  assert.equal(ball.vy, 0);
  assert.ok(ball.x + ball.r <= brickObj.x, 'ball should be pushed left of the brick');
  assert.equal(brickObj.alive, false);
