test('bounceBricks: corner hit flips BOTH components', () => {
  const brickObj = brick(200, 100);
  // Hit the top-left corner diagonally: moving down-right into the corner.
  const ball = { x: 194, y: 94, r: 7, vx: 300, vy: 300 };
  const prevX = ball.x - 30, prevY = ball.y - 30;
  const startVx = ball.vx, startVy = ball.vy;
  bounceBricks(ball, [brickObj], prevX, prevY);
  assert.equal(Math.sign(ball.vx), -Math.sign(startVx), 'vx should flip');
  assert.equal(Math.sign(ball.vy), -Math.sign(startVy), 'vy should flip');
  assert.equal(brickObj.alive, false);
  // The ball must not remain inside the brick.
  assert.ok(!(ball.x + ball.r > brickObj.x && ball.x - ball.r < brickObj.x + brickObj.w &&
              ball.y + ball.r > brickObj.y && ball.y - ball.r < brickObj.y + brickObj.h));
});

test('bounceBricks: a seam applies the bounce exactly once (no double-negation)', () => {
  // Two bricks stacked with the 8px gap; the ball (14px across) spans the seam.
  const top = brick(200, 100);
  const bottom = brick(200, 100 + BRICK_H + BRICK_GAP);
  // Ball sits in the gap and is being pushed down onto the bottom brick.
  const ball = { x: 236, y: bottom.y - 3, r: 7, vx: 0, vy: 300 };
  const prevX = ball.x, prevY = ball.y - 6;
  const n = bounceBricks(ball, [top, bottom], prevX, prevY).length;
  assert.ok(n >= 1, 'at least one brick should break');
  // vy must have flipped exactly once (still pointing up, not cancelled out).
  assert.ok(ball.vy < 0, 'vy should be up after a clean seam bounce');
  assert.equal(ball.vx, 0);
  // Ball left the seam region (no longer overlapping the bottom brick).
  assert.ok(ball.y + ball.r <= bottom.y, 'ball should sit above the bottom brick');
});

test('bounceBricks: fast ball cannot tunnel straight through a brick', () => {
  // Level 6 speed is 710 px/s; a capped 50 ms frame moves ~35.5 px, which is
  // more than enough to jump a brick of height 20 by pure endpoint overlap.
  const brickObj = brick(200, 100);
  const ball = { x: 236, y: 300, r: 7, vx: 0, vy: 710 };
  const prevY = ball.y - 100; // a long span ending inside (not just past) the brick
  bounceBricks(ball, [brickObj], ball.x, prevY);
  assert.equal(brickObj.alive, false, 'the swept path must catch the brick');
  assert.ok(ball.vy < 0, 'the ball should be deflected up, not fly through');
  assert.ok(ball.y + ball.r <= brickObj.y, 'ball must rest above the brick, not past it');
});

