test('bounceBricks: fast ball cannot tunnel straight through a brick', () => {
  // Level 6 speed is 710 px/s; a capped 50 ms frame moves ~35.5 px, which is
  // more than enough to jump a brick of height 20 by pure endpoint overlap.
  const brickObj = brick(200, 100);
  const ball = { x: 236, y: 300, r: 7, vx: 0, vy: 710 };
  const prevY = ball.y - 100; // a long span ending inside (not just past) the brick
  bounceBricks(ball, [brickObj], ball.x, prevY);
  assert.equal(brickObj.alive, false, 'the swept path must catch the brick');
  assert.ok(ball.vy < 0, 'the ball should be deflected up, not fly through');
  assert.ok(ball.y + ball.r <= brickObj.y, 'ball must rest above the brick, not past it');
});

